import{_ as o,o as r,c as e,a2 as s}from"./chunks/framework.BXA5Pi9t.js";const c=JSON.parse('{"title":"2019-07-17 :: Ceph Orchestration Meeting","description":"","frontmatter":{"title":"2019-07-17 :: Ceph Orchestration Meeting","date":"2019-07-17T00:00:00.000Z","updated":"2019-07-22T00:00:00.000Z","tags":["Ceph","Distributed Storage","Orchestration","Performance Optimization","Rook Module"],"categories":["视频总结"],"outline":"deep"},"headers":[],"relativePath":"posts/2019/2019-07-17_-_-_Ceph_Orchestration_Meeting.md","filePath":"posts/2019/2019-07-17_-_-_Ceph_Orchestration_Meeting.md","lastUpdated":1780460162000}'),i={name:"posts/2019/2019-07-17_-_-_Ceph_Orchestration_Meeting.md"};function l(n,t,a,p,h,g){return r(),e("div",null,[...t[0]||(t[0]=[s('<h3 id="会议纪要" tabindex="-1">会议纪要 <a class="header-anchor" href="#会议纪要" aria-label="Permalink to &quot;会议纪要&quot;">​</a></h3><p><strong>会议时间</strong>： 2019年7月17日</p><p><strong>参会人员</strong>： [所有参会人员姓名]</p><p><strong>会议主题</strong>： Ceph分布式存储项目进展及问题讨论</p><p><strong>会议内容</strong>：</p><p><strong>一、Ceph Orchestrator性能优化</strong></p><ol><li><strong>问题</strong>： Ceph Orchestrator，尤其是Dashboard和Kiva的使用，性能较慢。</li><li><strong>解决方案</strong>： <ul><li>探索使用Costner改进的Rook模块，以提高性能。</li><li>讨论将Rook模块优化纳入Ceph Orchestrator的拉取请求中。</li></ul></li></ol><p><strong>二、Ceph Dashboard集成</strong></p><ol><li><strong>问题</strong>： Ceph Dashboard集成存在问题，如服务显示不正常、软盘和磁盘代码位置不合理等。</li><li><strong>解决方案</strong>： <ul><li>确认软盘和磁盘代码功能在Ceph中已有实现，但位置不太合理。</li><li>讨论优化软盘和磁盘代码功能，使其更易于使用。</li></ul></li></ol><p><strong>三、Ceph Rook模块</strong></p><ol><li><strong>问题</strong>： Ceph Rook模块需要更多关注和维护。</li><li><strong>解决方案</strong>： <ul><li>鼓励Young更多参与Ceph Rook模块的上游维护。</li></ul></li></ol><p><strong>四、Ceph测试Orchestrator</strong></p><ol><li><strong>问题</strong>： Ceph测试Orchestrator的功能需要增强，以更好地支持集成测试。</li><li><strong>解决方案</strong>： <ul><li>鼓励开发人员增强测试Orchestrator的功能，以便返回更多数据。</li></ul></li></ol><p><strong>五、其他</strong></p><ol><li>讨论了Ceph Inventory命令的改进，以便更好地支持磁盘识别。</li><li>讨论了Ceph Dashboard的命名一致性问题和SSH Orchestrator的简单设置。</li></ol><p><strong>后续行动计划</strong>：</p><ol><li>Costner将修改Rook模块，以提高Ceph Orchestrator性能。</li><li>开发人员将优化Ceph Dashboard和Rook模块。</li><li>Young将更多参与Ceph Rook模块的上游维护。</li><li>开发人员将增强测试Orchestrator的功能。</li></ol>',17)])])}const C=o(i,[["render",l]]);export{c as __pageData,C as default};
